 const chosen=chosenRoute();$('#preview-route').innerHTML=`<div class="route-endpoint"><small>DEPARTURE</small><strong>${esc(chosen[0].ko)}</strong></div><span class="route-connector">${chosen.length} STOPS</span><div class="route-endpoint"><small>DESTINATION</small><strong>${esc(chosen.at(-1).ko)}</strong></div>`;
