function finish(complete){if(resultPending)return;resultPending=true;input.disabled=true;$('#submit-answer').disabled=true;$('#hint').disabled=true;renderConsole();if(complete){journal.records.unshift({line:currentLine().ko,branch:selection.branch,mode:run.mode,seconds:run.elapsed(),accuracy:run.accuracy,hints:run.hints,cpm:speedSnapshot(run).cpm,units:run.units,date:new Date().toISOString(),from:run.stations[0].ko,to:run.stations.at(-1).ko});journal.records=journal.records.slice(0,30);saveJournal();}sound(complete?'finish':'wrong');showModal(`<div class="exit-content"><p class="eyebrow">${complete?'A JOURNEY TO REMEMBER':'TIME IS UP'}</p><h2>${complete?'종점에 도착했어요!':'이번 여행은 여기까지'}</h2><p>${esc(currentLine().ko)} · ${esc(modes[run.mode])}<br>${esc(run.stations[0].ko)} → ${esc(run.stations.at(-1).ko)}</p><p class="result-value">${run.index}<small> / ${run.stations.length} 역</small></p><div class="result-stats"><div><strong>${speedSnapshot(run).cpm}<small> 타/분</small></strong><span>평균 입력 속도</span></div><div><strong>${formatTime(run.elapsed())}</strong><span>운행 시간</span></div><div><strong>${run.accuracy}%</strong><span>정확도</span></div><div><strong>${run.hints}회</strong><span>사용한 힌트</span></div></div><p>누적 ${run.units}타 · 정답 입력 기준<br>발견한 ${visited.size}개 동네가 여행 수첩에 담겼어요.</p><div class="result-actions"><button id="result-retry" class="outline-button">다시 운행</button><button id="result-menu" class="primary-button">다른 노선 고르기 →</button></div></div>`,{pause:false,canEscape:false});$('#result-retry').onclick=()=>{$('#modal').close();returnToSetup();launch();};$('#result-menu').onclick=()=>{$('#modal').close();returnToSetup();};}
function zoom(value){setSetting('zoom',Math.max(75,Math.min(250,Math.round(value/5)*5)));}$('#zoom-in').onclick=()=>zoom(settings.zoom+15);$('#zoom-out').onclick=()=>zoom(settings.zoom-15);$('#zoom-slider').oninput=e=>zoom(Number(e.target.value));$$('[data-theme-choice]').forEach(b=>b.onclick=()=>setSetting('theme',b.dataset.themeChoice));$('#follow-train').onclick=()=>setSetting('follow',!settings.follow);$('#toggle-story').onclick=()=>{storyVisible=!storyVisible;updateTools();};$('#close-story').onclick=()=>{storyVisible=false;updateTools();};
function segment(key,choices){return `<div class="segmented">${choices.map(([value,label])=>`<button data-setting="${key}" data-value="${value}" class="${String(settings[key])===String(value)?'active':''}" aria-pressed="${String(settings[key])===String(value)}">${esc(label)}</button>`).join('')}</div>`;}
function settingRow(name,title,description,control){return `<div class="setting-row"><div><span data-icon="${name}"></span><div><strong>${title}</strong><p>${description}</p></div></div>${control}</div>`;}
function renderSettings(){const labels={general:['sliders','일반','화면과 플레이 방식을 내 취향에 맞춰요.'],sound:['volume','사운드','작은 도착 알림으로 운행의 리듬을 느껴요.'],map:['map','지도','나에게 맞는 도쿄의 풍경을 골라 보세요.']},[name,title,description]=labels[settingsTab];let html=`<div class="settings-section-title"><span data-icon="${name}"></span><div><h3>${title}</h3><p>${description}</p></div></div>`;
 if(settingsTab==='general')html+=settingRow('sun','화면 모드','노선 선택과 운행 화면에 함께 적용됩니다.',segment('theme',[['light','화이트'],['dark','다크']]))+settingRow('train','지하철 이동 방식','다이내믹은 맞게 입력하는 동안 열차가 조금씩 움직여요.',segment('movement',[['classic','클래식'],['dynamic','다이내믹']]))+settingRow('keyboard','다음 역 이동 방식','직접 출발은 Enter / Space, 자동 출발은 정답 완성 시 이동해요.',segment('departure',[['manual','직접 출발'],['auto','자동 출발']]))+settingRow('sliders','백스페이스 삭제 방식','조합이 끝난 한글을 지우는 단위를 선택해요. IME 조합 중에는 입력기의 동작을 따릅니다.',segment('backspace',[['jamo','자모 단위'],['letter','글자 단위']]))+settingRow('timer','출발 카운트다운','다음 운행부터 적용됩니다.',segment('countdown',[[3,'3초'],[5,'5초']]))+settingRow('map','역 이름 표시 언어','정답 입력은 어느 언어든 가능해요.',segment('language',[['ko','한국어'],['en','English'],['ja','日本語']]));
 if(settingsTab==='sound')html+=settingRow('volume','게임 효과음','카운트다운, 도착, 오답, 종점 알림을 켜거나 꺼요.',segment('sound',[[true,'켜기'],[false,'끄기']]))+settingRow('sliders','효과음 음량','배경음악 없이 짧은 효과음만 재생됩니다.',`<div><input id="volume-slider" type="range" min="0" max="100" value="${settings.volume}" aria-label="효과음 음량"><output id="volume-value">${settings.volume}%</output></div>`)+`<button id="test-sound" class="outline-button">${icon('volume')} 도착 알림 미리 듣기</button>`;
 if(settingsTab==='map')html+=`<div class="skin-buttons"><button class="skin-card ${settings.skin==='garden'?'active':''}" data-setting="skin" data-value="garden"><span></span><strong>도쿄 산책</strong><small>수채화 같은 초록과 도시의 골목</small></button><button class="skin-card blueprint ${settings.skin==='blueprint'?'active':''}" data-setting="skin" data-value="blueprint"><span></span><strong>노선 아틀라스</strong><small>또렷한 격자 위에 집중하는 운행</small></button></div>`+settingRow('locate','열차 따라가기','열차를 화면 중심으로 따라가요. 지도를 드래그하면 자유 탐색으로 바뀝니다.',segment('follow',[[true,'따라가기'],[false,'자유 탐색']]))+settingRow('map','명소와 먹거리 그림','직접 제작한 랜드마크와 음식 삽화를 표시해요.',segment('landmarks',[[true,'표시'],[false,'숨기기']]))+settingRow('compass','지도에 표시할 정보','명소 또는 먹거리에 집중할 수 있어요.',segment('layer',[['all','전체'],['sight','명소'],['food','먹거리']]))+settingRow('keyboard','역 이름 라벨','지도의 역 이름 표시를 선택해요.',segment('labels',[[true,'표시'],[false,'숨기기']]))+settingRow('plus','지도 확대 비율','오른쪽 지도 도구에서도 조절할 수 있어요.',`<div><input id="settings-zoom" type="range" min="75" max="250" step="5" value="${settings.zoom}" aria-label="설정 지도 확대 비율"><output id="settings-zoom-value">${settings.zoom}%</output></div>`);
 html+='<p class="settings-note">설정창을 연 동안 운행 시간은 잠시 멈춰요. 설정과 여행 수첩은 이 브라우저에만 저장되며, 다른 기기와 동기화되지 않습니다.</p>';$('#settings-content').innerHTML=html;hydrateIcons($('#settings-content'));$$('[data-settings-tab]').forEach(b=>b.classList.toggle('active',b.dataset.settingsTab===settingsTab));$$('[data-setting]').forEach(b=>b.onclick=()=>{const raw=b.dataset.value,value=['true','false'].includes(raw)?raw==='true':b.dataset.setting==='countdown'?Number(raw):raw;setSetting(b.dataset.setting,value);renderSettings();});
 if($('#volume-slider'))$('#volume-slider').oninput=e=>{settings.volume=Number(e.target.value);persistSettings();$('#volume-value').textContent=`${settings.volume}%`;};if($('#settings-zoom'))$('#settings-zoom').oninput=e=>{zoom(Number(e.target.value));$('#settings-zoom-value').textContent=`${settings.zoom}%`;};if($('#test-sound'))$('#test-sound').onclick=()=>sound();
}
function openSettings(){if(countdownTimer||$('dialog[open]'))return;if(!pauseForDialog())return;renderSettings();$('#settings-dialog').showModal();}
$$('.open-settings').forEach(b=>b.onclick=openSettings);$('#close-settings').onclick=()=>$('#settings-dialog').close();$('#settings-dialog').addEventListener('close',resumeFromDialog);$$('[data-settings-tab]').forEach(b=>b.onclick=()=>{settingsTab=b.dataset.settingsTab;renderSettings();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&screen==='game'&&!$('dialog[open]')){e.preventDefault();requestLeave();}if(e.key==='Enter'&&screen==='setup'&&!$('dialog[open]')&&!['INPUT','SELECT','BUTTON','TEXTAREA','A'].includes(document.activeElement?.tagName)){e.preventDefault();launch();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(countdownTimer)countdownRemaining=Math.max(1,Math.ceil((countdownEnd-performance.now())/1000));if(run?.status==='running'){if(run.expired()){run.stop();finish(false);}else{run.pause();hiddenPause=true;input.disabled=true;}}}else{if(countdownTimer)countdownEnd=performance.now()+countdownRemaining*1000;if(hiddenPause&&run?.status==='paused'&&!$('dialog[open]')){hiddenPause=false;showModal(`<div class="exit-content"><span class="exit-emblem">${icon('pause')}</span><h2>잠시 쉬어 가는 중</h2><p>화면을 벗어나 있는 동안 운행 시간을 멈췄어요.<br>준비되면 다시 출발해요.</p><button id="resume-trip" class="primary-button">운행 계속하기 →</button></div>`,{pause:false,canEscape:false});$('#resume-trip').onclick=()=>{run.resume();input.disabled=run.moving;$('#submit-answer').disabled=run.moving;$('#modal').close();if(!run.moving)input.focus();};}}});
function showView(view){screen=view;$('#setup-view').hidden=view!=='setup';$('#journal-view').hidden=view!=='journal';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='journal')renderJournal();}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
function renderJournal(){$('#journal-stats').textContent=`발견한 동네 ${visited.size}곳 · 최근 완주 기록 ${journal.records.length}회`;
 $('#journal-places').innerHTML=visited.size?[...visited].map(id=>{const s=stationById.get(id),p=getPlace(s);return `<article class="journal-card"><div class="story-art">${illustration(p.icon,{postcard:true})}</div><h3>${esc(s.ko)}</h3><small>${esc(s.en)} · ${esc(s.ja)}</small><p>${esc(p.generic?'이름을 익힌 새로운 동네':p.sight)}</p></article>`;}).join(''):'<p class="empty-state">아직 빈 수첩이에요. 첫 번째 역에 도착하면<br>나만의 도쿄 여행이 기록되기 시작해요.</p>';
 $('#journal-records').innerHTML=journal.records.length?journal.records.map(r=>`<div class="record-row">${esc(r.date.slice(0,10))} · ${esc(r.line)} ${r.branch?'지선':''} · ${esc(modes[r.mode])} · ${formatTime(r.seconds)} · 정확도 ${r.accuracy}%${Number.isFinite(r.cpm)?` · ${r.cpm}타/분`:''} · 힌트 ${r.hints}회${r.from?`<br>${esc(r.from)} → ${esc(r.to)}`:''}</div>`).join(''):'<p class="story-description">아직 완주 기록이 없어요. 한 노선을 끝까지 달려 보세요.</p>';}
$('#export-journal').onclick=()=>{const blob=new Blob([JSON.stringify({title:'도쿄 한 정거장 여행 수첩',exportedAt:new Date().toISOString(),stations:[...visited].map(id=>stationById.get(id)),records:journal.records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tokyo-eki-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);};
$('#help').onclick=()=>showModal(`<p class="eyebrow">WELCOME ABOARD</p><h2>도쿄로 떠나는 타이핑 여행</h2><ol><li>노선과 운행 구간, 플레이 방식을 선택하세요.</li><li>운행 시작을 누르면 카운트다운 후 출발해요.</li><li>아래 중앙에 표시된 역을 입력하고 Enter 또는 Space로 출발하세요. 띄어쓰기를 넣으려면 정답 완성 전에 입력하면 됩니다.</li><li>다이내믹 모드에서는 맞게 입력하는 만큼 열차가 움직여요. 자동 출발은 톱니바퀴에서 켤 수 있어요.</li><li>왼쪽에 이전 역, 오른쪽에 다음 역이 표시돼요. 암기 모드는 아직 도착하지 않은 역 이름을 숨겨요.</li><li>지도를 드래그해 둘러보고, 오른쪽 조준점 버튼으로 열차를 다시 따라갈 수 있어요.</li></ol><p>오른쪽 도구로 화이트·다크 모드와 확대 비율을 바꿔 보세요. 톱니바퀴에서는 화면, 이동, 삭제 방식, 사운드, 지도 스킨을 조절할 수 있어요.</p><p>한국어·영어·일본어 역명을 모두 인정합니다. 일본어 IME 조합을 확정한 뒤 Enter를 다시 눌러 주세요. 기록은 이 브라우저에 저장돼요.</p><p><strong>타수 계산:</strong> 한글은 두벌식 자모 기준(한=3타, 과=3타), 영어는 글자당 1타, 일본어는 입력된 문자당 1타로 셉니다. 공백과 구분기호는 제외하며, 정답을 이룬 누적 타수와 현재 맞게 입력한 부분을 합해 실제 운행 시간으로 나눈 평균 타/분입니다. 삭제·오답을 중복 적립하지 않고 카운트다운·일시정지 시간은 제외합니다. IME로 변환한 일본어는 실제 물리 키 입력 수와 다를 수 있습니다.</p>`);
$('#sources').onclick=()=>showModal(`<h2>지도와 자료 안내</h2><p>역 이름과 순서는 <a href="https://www.tokyometro.jp/kr/subwaymap/index.html" target="_blank" rel="noopener noreferrer">도쿄메트로 공식 노선 자료</a>를 참고했어요. 확인일: 2026년 10월 30일.</p><p>9개 노선과 마루노우치선 지선을 플레이할 수 있어요. 도에이 지하철·JR·사철은 포함하지 않습니다. 지도는 주변 동네를 익히기 위한 학습용 개략도입니다.</p><p>긴자선 전체와 주요 관광역에 동네 이야기를 제공해요. 나머지 역의 개별 관광 정보는 준비 중이며 공식 관광 안내로 연결됩니다.</p><p>관광 안내는 <a href="https://www.gotokyo.org/kr/" target="_blank" rel="noopener noreferrer">GO TOKYO</a>와 <a href="https://www.japan.travel/en/" target="_blank" rel="noopener noreferrer">JNTO</a>를 참고했어요. 지도와 음식·건축물 그림은 직접 제작했습니다. 기본 게임 방식은 <a href="https://metrotyping.kr/" target="_blank" rel="noopener noreferrer">Metro Typing</a>을 참고했어요.</p><p>개인정보를 전송하는 로그인·분석·광고 기능은 없으며, 여행 기록과 설정은 브라우저에만 저장됩니다. 외부 여행 안내 링크를 열면 해당 사이트로 이동합니다.</p>`);
$('#art-definitions').innerHTML=artDefs;hydrateIcons();renderLines();applySettings();$('#collection-count').textContent=visited.size;
previewMap.build(lines.find(l=>l.id==='G').stations,{...settings,follow:false,zoom:100},{index:-1});
